import{_ as i,o as l,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"An Open Source Distributed Rate-limiting Service for Ceph-object and Other HTTP APIs- Jacques Heunis","description":"","frontmatter":{"title":"An Open Source Distributed Rate-limiting Service for Ceph-object and Other HTTP APIs- Jacques Heunis","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","Distributed Storage","Rate-limiting","Open Source","QoS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/An_Open_Source_Distributed_Rate-limiting_Service_for_Ceph-object_and_Other_HTTP_APIs-_Jacques_Heunis.md","filePath":"posts/2025/An_Open_Source_Distributed_Rate-limiting_Service_for_Ceph-object_and_Other_HTTP_APIs-_Jacques_Heunis.md","lastUpdated":1780459816000}'),r={name:"posts/2025/An_Open_Source_Distributed_Rate-limiting_Service_for_Ceph-object_and_Other_HTTP_APIs-_Jacques_Heunis.md"};function s(n,e,_,a,u,p){return l(),t("div",null,[...e[0]||(e[0]=[o('<h3 id="ceph-分布式对象存储限速服务开源项目总结" tabindex="-1">Ceph 分布式对象存储限速服务开源项目总结 <a class="header-anchor" href="#ceph-分布式对象存储限速服务开源项目总结" aria-label="Permalink to &quot;Ceph 分布式对象存储限速服务开源项目总结&quot;">​</a></h3><p><strong>会议主题</strong>： Bloomberg 团队分享了其开发的针对 Ceph 对象存储的分布式限速系统（代号为 we QoS），该系统旨在管理用户请求速率、数据传输速率及并发请求，以提高 Ceph 存储系统的服务质量（QoS）。</p><p><strong>核心讨论内容</strong>：</p><ol><li><p><strong>背景与挑战</strong>：</p><ul><li>Bloomberg 的存储工程团队为内部团队提供对象存储服务，类似私有云，服务于不同业务团队，流量模式多样。</li><li>需确保系统稳定性，防止单个用户占用过多资源（如 CPU、内存、OSD 负载）。</li><li>早期使用硬件负载均衡器进行 IP 限速，但难以适应集群扩展和多租户需求。</li></ul></li><li><p><strong>解决方案：we QoS 系统</strong>：</p><ul><li><strong>核心功能</strong>： <ul><li>请求速率限制（RPS）</li><li>数据传输速率限制（带宽）</li><li>并发请求控制（防止资源耗尽）</li></ul></li><li><strong>技术栈</strong>： <ul><li>HAProxy（核心代理层，通过 Lua API 注入限流逻辑）</li><li>独立服务（非 Ceph 内置，易于调试和扩展）</li></ul></li><li><strong>优势</strong>： <ul><li>协议无关（支持 S3、管理 API 等 HTTP 服务）</li><li>动态配置（JSON 文件定义限速策略，支持热更新）</li></ul></li></ul></li><li><p><strong>演进与优化</strong>：</p><ul><li>初始版本（约 700 行代码）：仅限请求速率。</li><li>新增功能： <ul><li>并发控制（防止用户占用过多连接/内存）</li><li>差异化限速（基于 HTTP Method 和 S3 Operation）</li><li>支持短时凭证（Ceph Squid 版本引入的 <code>Accounts</code> 功能）</li></ul></li></ul></li><li><p><strong>开源与社区反馈</strong>：</p><ul><li>we QoS 已在 GitHub 发布。</li><li>Q&amp;A 重点： <ul><li>匿名请求：未认证请求共享同一限速池。</li><li>批量操作：按操作类型整体限速。</li><li>临时调整限速：修改 JSON 配置文件并触发动态加载。</li></ul></li></ul></li></ol><p><strong>关键决定与行动计划</strong>：</p><ol><li>推广使用：鼓励社区测试 we QoS，反馈需求。</li><li>持续优化： <ul><li>增加对请求体动态评估的支持。</li><li>探索与 Ceph Dashboard 集成，提供可视化限速管理。</li></ul></li></ol><p><strong>保留的关键术语</strong>：</p><ul><li>Ceph, distributed storage, OSD, RADOS, S3, HAProxy, QoS, CRUSH algorithm, short-lived credentials, concurrency control</li></ul><p><strong>后续跟进</strong>：</p><ul><li>GitHub 协作：社区贡献与问题跟踪。</li><li>用户案例收集：验证多场景适用性。</li></ul><p>通过这个开源项目，Bloomberg 为 Ceph 对象存储提供了一种有效的限速机制，以优化资源使用并提高系统性能。项目的开源使得其他组织也可以受益于这一解决方案。</p>',11)])])}const g=i(r,[["render",s]]);export{d as __pageData,g as default};
